Translate("ruRU", "alterac-mountains", {
	title = "Альтеракские горы",
	aliases = { "Альтерак", "королевство Альтерак" },
	sections = {
		{
			title = "Обзор",
			text = [=[Альтеракские горы высятся к северу от {link:hillsbrad-foothills}Предгорий Хилсбрада{/link} — стена снега и серого камня между берегами {red:lordamere-lake}Озера Лордамер{/red} и мертвыми Чумными землями. Некогда они были отдельным королевством. Его столица лежит в руинах на высоких перевалах, а имя его до сих пор произносят при дворах людей как проклятие, ибо Альтерак предал {link:alliance}Альянс{/link} в самый темный его час. Теперь горы принадлежат тому, кто сумеет их удержать: изгнанным дворянам и их головорезам, {link:ogres}огр{/link}ам, увенчанным крадеными реликвиями, волшебникам, наемным убийцам, {link:orcs}орк{/link}ам и {link:dwarves}дворф{/link}ам.]=],
		},
		{
			title = "Истоки",
			text = [=[Альтерак был одним из городов-государств, которые люди {link:arathor}Аратора{/link} основали в глуши после смерти короля {link:thoradin}Торадин{/link}а, когда их империя переросла стены {link:stromgarde-keep}Стром{/link}а. Он богател на дорогах через горы и со временем стал одним из человеческих королевств, поделивших между собой старую империю. Род Перенольдов правил им из замка в высоком городе. Его кормили хутора Высокогорья, а маги {link:dalaran}Даларана{/link} были его соседями по ту сторону озера.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:syndicate}Синдикат{/link} удерживает большую часть старого королевства. Его лорды сделали город-призрак {link:strahnbrad}Странбрад{/link} своей крепостью, а {link:the-uplands}Высокогорье{/link} — охотничьими угодьями, и лорд {link:lord-aliden-perenolde}Алиден Перенольд{/link} держит свой двор в поместье на берегу озера. Рядом с ним стоят чужаки в черных одеяниях. Разрушенная столица принадлежит {link:ogres}огр{/link}ам Раздробленного Хребта и их полководцу {link:mug-thol}Маг'тол{/link}у, который носит корону, что хочет вернуть {link:sylvanas-windrunner}Темная Госпожа{/link}. На западе стоит отстроенный {link:dalaran}Даларан{/link}, и его великий барьер пал. На востоке убийцы Черного Ворона следят за Синдикатом из своего тайного поместья. У входа в Альтеракскую долину {link:dwarves}дворф{/link}ы {link:kingdom-of-ironforge}Стальгорна{/link} и {link:orcs}орк{/link}и клана Северного Волка собирают солдат для собственной войны. И {link:southshore}Южнобережье{/link}, и {link:tarren-mill}Мельница Таррен{/link} посылают в снега охотников, и у каждого поселения на то свои причины.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:syndicate}Синдикат{/link}.{/b} Падшие дворяне Альтерака и воры, грабители и маги теней, что им служат.
• {b}{link:crushridge-ogres}Огры Раздробленного Хребта{/link}.{/b} Отряд {link:ogres}огр{/link}ов, захвативший разрушенную столицу и вырывший логово в холмах за ней.
• {b}Маги {link:dalaran}Даларан{/link}а.{/b} {link:kirin-tor}Кирин-Тор{/link} и его стражи, работники и связанные чарами элементали.
• {b}Лига убийц.{/b} Разбойники Черного Ворона, которые не подчиняются ни одному королю.
• {b}{link:stormpike-guard}Стража Грозовой Вершины{/link} и {link:frostwolf-clan}клан Северного Волка{/link}.{/b} {link:dwarves}Дворфы{/link} и {link:orcs}орк{/link}и, воюющие за Альтеракскую долину.
• {b}Звери.{/b} Йети в пещерах, горные львы на склонах и медведи на нижних холмах.]=],
		},
		{
			title = "История",
			text = [=[• {b}Королевство.{/b} Веками Альтерак был малым, но гордым королевством севера и часто враждовал со своим соседом, {link:stromgarde-keep}Стромгард{/link}ом.
• {b}{link:second-war}Вторая война{/link}.{/b} Король {link:aiden-perenolde}Айден Перенольд{/link} с самого начала сомневался в {link:alliance}Альянс{/link}е. Когда {link:horde}Орда{/link} дошла до его гор, он заключил тайный договор с вождем {link:orgrim-doomhammer}Оргримом Молотом Рока{/link} и открыл южные перевалы. {link:orcs}Орки{/link} перешли горы за дни вместо месяцев и осадили столицу {link:lordaeron}Лордерона{/link}.
• {b}Падение.{/b} Когда о предательстве стало известно, армии Альянса двинулись на Альтерак. Король {link:terenas-menethil}Теренас Менетил{/link} низложил предателя и держал его пленником в его же дворце. Королевство больше не поднялось, а народ его рассеялся.
• {b}Чума.{/b} В {link:third-war}Третью войну{/link} {link:scourge}Плеть{/link} прокатилась по Лордерону, а {link:archimonde}Архимонд{/link} сокрушил {link:dalaran}Даларан{/link} за озером. Тот порядок, что еще оставался в горах, умер вместе с ними.]=],
		},
		{
			title = "Предания гор",
			text = [=[• Тиару Перенольдов, наследие старого королевского дома, сделали ювелиры {link:ironforge}Стальгорн{/link}а и украсили изумрудами. Она пропала, когда пал Альтерак. Говорят, теперь ее носит при себе {link:ogres}огр{/link}-маг Раздробленного Хребта.
• Мировой судья Южнобережья был убит наемными убийцами, которых так и не нашли. Его преемник полагает, что их нанял {link:syndicate}Синдикат{/link}.
• Охотники говорят, что на высотах над Промерзшей пещерой бродит огромный йети по кличке Ледяная Пасть.]=],
		},
	},
})

Translate("ruRU", "ruins-of-alterac", {
	title = "Руины Альтерака",
	aliases = { "город Альтерак" },
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Альтерака когда-то были столицей королевства, обнесенным стенами городом на высоких перевалах. Здесь держал двор король {link:aiden-perenolde}Айден Перенольд{/link}, и здесь он объявил своим офицерам, что {link:alterac-mountains}Альтерак{/link} встанет на сторону Орды. Когда {link:alliance}Альянс{/link} пришел за ним, его народ бежал, и город так и не был отстроен. Теперь разбитые улицы удерживают {link:ogres}огр{/link}ы Раздробленного Хребта. Их полководец {link:mug-thol}Маг'тол{/link} устроил логово в старом дворце, единственном здании, что еще стоит целым. {link:forsaken}Отрекшиеся{/link} из Мельницы Таррен поклялись насадить его голову на пику над этими стенами.]=],
		},
	},
})

Translate("ruRU", "strahnbrad", {
	title = "Странбрад",
	sections = {
		{
			title = "Обзор",
			text = [=[Странбрад был городком в восточных предгорьях, на дороге между {link:alterac-mountains}Альтерак{/link}ом и землями {link:lordaeron}Лордерон{/link}а. В канун {link:third-war}Третьей войны{/link} {link:orcs}орк{/link}и напали на него ради рабов, и принц {link:arthas-menethil}Артас Менетил{/link} пришел слишком поздно, чтобы спасти многих его жителей. Сегодня это город-призрак и главный оплот {link:syndicate}Синдиката{/link}. Его лорды собираются в пустых залах, а в старых темницах сидят их пленники. Орка {link:gol-dir}Гол'дир{/link}а держали там в рабстве и заставляли копать и таскать тяжести для своих тюремщиков. Мировой судья Южнобережья хочет получить перстни-печатки дворян, что прячутся среди здешних воров.]=],
		},
	},
})

Translate("ruRU", "crushridge-hold", {
	title = "Логово Раздробленного Хребта",
	aliases = { "Кровавая низина", "Перекресток Висельников" },
	sections = {
		{
			title = "Обзор",
			text = [=[Логово Раздробленного Хребта — {link:ogres}огр{/link}ское логово, которое огры этого племени вырыли в холмах возле разрушенной столицы. Его пещеры и стоянки кишат громилами, молотобойцами и магами, а глубже в горах огры держат второе логово в Кровавой низине. Их дозоры стерегут Перекресток Висельников у старой разрушенной башни. Маршал Южнобережья страшится дня, когда огры почувствуют себя достаточно уверенно, чтобы спуститься в предгорья, и хорошо платит за каждую костяшку пальца, которую приносят его охотники.]=],
		},
	},
})

Translate("ruRU", "the-uplands", {
	title = "Высокогорье",
	sections = {
		{
			title = "Обзор",
			text = [=[Высокогорье — высокие холмы северного {link:alterac-mountains}Альтерак{/link}а, к северу от {link:strahnbrad}Странбрад{/link}а. Это были пахотные земли старого королевства. Теперь это сердце владений {link:syndicate}Синдиката{/link}, который здесь сильнее всего. {link:baron-vardus}Барон Вардус{/link} держит в этих холмах свои лагеря, и здесь же ждут маги теней ордена Пробуждения Аргуса, пришедшие в Альтерак как союзники Синдиката. Мировой судья Южнобережья посылает своих охотников на север, в Высокогорье, когда ему нужна голова дворянина.]=],
		},
	},
})

Translate("ruRU", "dandred-s-fold", {
	title = "Овчарня Дандреда",
	aliases = { "Мглистый берег" },
	sections = {
		{
			title = "Обзор",
			text = [=[Овчарня Дандреда — поместье с небольшой гаванью на Мглистом берегу, там, где западное {link:the-uplands}Высокогорье{/link} встречается с {red:lordamere-lake}Озером Лордамер{/red}. Это дом лорда {link:lord-aliden-perenolde}Алиден{/link}а Перенольда, который называет себя владыкой этих земель. Его двери охраняют убийцы и громилы {link:syndicate}Синдикат{/link}а. На верхнем этаже живет его любовница {link:elysa}Элиза{/link}, а рядом с ним стоит {link:nagaz}Нагаз{/link}, {link:orcs}орк{/link}, говорящий от имени ордена Пробуждения Аргуса. Воины Мельницы Таррен знают сюда дорогу. Знают ее и охотники Южнобережья.]=],
		},
	},
})

Translate("ruRU", "sofera-s-naze-and-corrahn-s-dagger", {
	title = "Возвышенность Соферы и Уступ Коррана",
	aliases = { "Возвышенность Соферы", "Уступ Коррана" },
	sections = {
		{
			title = "Обзор",
			text = [=[Возвышенность Соферы и Уступ Коррана — два холма, что спускаются от гор к предгорьям, к северу и к западу от Мельницы Таррен. {link:syndicate}Синдикат{/link} держит лагеря на обоих. Отсюда его грабители и воры спускаются разбойничать на дорогах {link:hillsbrad-foothills}Хилсбрад{/link}а, и отсюда, как полагают в {link:southshore}Южнобережье{/link}, пришли убийцы, погубившие его прежнего мирового судью. На холме возле одного из этих лагерей лежит раненый подручный Синдиката по имени Валик и выторговывает себе последний глоток выпивки.]=],
		},
	},
})

Translate("ruRU", "growless-cave", {
	title = "Промерзшая пещера",
	sections = {
		{
			title = "Обзор",
			text = [=[Промерзшая пещера открывается на холодных высотах в середине {link:alterac-mountains}Альтерак{/link}а. Это логово горных йети, и у ее входа порой видят белого йети по кличке Скоул. Есть у пещеры и более мрачная история. Волшебник {link:helcular}Хелькулар{/link}, который стремился стать личем, зажег в ней один из трех своих ритуальных костров: Пламя Узела. Его ученик в Мельнице Таррен до сих пор помнит дорогу. Охотники говорят, что, если сжечь на этом пламени мясо, с вершин спустится {link:ogres}огр{/link}омный йети Ледяная Пасть.]=],
		},
	},
})

Translate("ruRU", "chillwind-point", {
	title = "Берег Промозглого Ветра",
	sections = {
		{
			title = "Обзор",
			text = [=[Берег Промозглого Ветра — возвышенность на дальнем восточном краю {link:alterac-mountains}Альтерак{/link}а, где через ущелье дует холодный ветер из Чумных земель. На ней стоят руины старого поселения троллей, намного более древнего, чем любое человеческое королевство в этих краях. Тролль-отшельник {link:bath-rah-the-windwatcher}Бат'ра Наблюдатель Ветра{/link} разбил лагерь у реки внизу. Он годами наблюдает за этими руинами, ожидая дня, когда придет герой, чтобы сразиться с повелителем ветра, который там обитает.]=],
		},
	},
})

Translate("ruRU", "ravenholdt-manor", {
	title = "Поместье Черного Ворона",
	aliases = { "Черный Ворон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Поместье Черного Ворона прячется в восточных холмах, где {link:alterac-mountains}Альтерак{/link} встречается с {link:hillsbrad-foothills}Хилсбрад{/link}ом, над руинами {link:durnholde-keep}Дарнхольд{/link}а. Открытой дороги к нему нет. Это дом лорда Джораха Черного Ворона и резиденция Лиги убийц. Здесь обучают, проверяют и испытывают лучших воров и убийц северных земель. Чужакам здесь не рады. Те, кто является без приглашения, редко находят дверь, а приглашенные должны сперва доказать свою хитрость уже затем, чтобы до нее добраться. Сообщество годами воюет с {link:syndicate}Синдикатом{/link}.]=],
		},
	},
})

Translate("ruRU", "lordamere-internment-camp", {
	title = "Лордамерские выселки",
	sections = {
		{
			title = "Обзор",
			text = [=[Лордамерские выселки стоят на холме возле {link:dalaran}Даларана{/link}. После {link:second-war}Второй войны{/link} это был один из {link:internment-camps}лагерей для интернированных{/link} в {link:lordaeron}Лордерон{/link}е, где побежденных {link:orcs}орк{/link}ов держали за стенами. Орков больше нет. Сегодня {link:the-wizards-of-ambermill}волшебники Даларана{/link} используют лагерь как собственную тюрьму. Четверо {link:forsaken}Отрекшихся{/link}, укравших артефакты из хранилища в {link:undercity}Подгород{/link}е, бежали сюда, и маги схватили их и посадили под карантин. {link:warden-belamoore}Надзирательница Беламур{/link} управляет лагерем и изучает то, что несли с собой воры. {link:sylvanas-windrunner}Темная Госпожа{/link} хочет вернуть свои артефакты.]=],
		},
	},
})

Translate("ruRU", "alterac-valley", {
	title = "Альтеракская долина",
	sections = {
		{
			title = "Обзор",
			text = [=[К югу от высоких пиков туннель ведет в {link:alterac-mountains}Альтерак{/link}скую долину, край льда и сосен между горами. {link:frostwolf-clan}Клан Северного Волка{/link}, клан {link:orcs}орк{/link}ов, считает долину своим домом. {link:dwarves}Дворфы{/link} Стражи Грозовой Вершины пришли туда искать реликвии и руду и намерены забрать эту землю для {link:kingdom-of-ironforge}Стальгорна{/link}. У входа в туннель обе армии держат лагеря. Их офицеры принимают новых солдат, испытывают их и посылают в долину. Бои внутри никогда по-настоящему не прекращаются.]=],
		},
	},
})

Translate("ruRU", "old-dalaran-ruins", {
	title = "Руины старого Даларана",
	sections = {
		{
			title = "Обзор",
			text = [=[Не весь {link:dalaran}Даларан{/link} поднялся вновь. Когда {link:archimonde}Архимонд{/link} сокрушил город в {link:third-war}Третью войну{/link}, его окраины были разрушены вместе с его сердцем. Маги возвели свой новый город за барьером, но руины старого по-прежнему лежат на берегах {red:lordamere-lake}Озера Лордамер{/red}. Когда-то их обходили дозором волшебники города и связанные чарами элементали, а ученые Отрекшихся полагают, что среди камней все еще лежат магические сокровища. Теперь, когда барьера нет, руины открыты всякому, кому хватит смелости их обыскать.]=],
		},
	},
})

Translate("ruRU", "lord-jorach-ravenholdt", {
	title = "Лорд Джорах Черный Ворон",
	subtitle = "Лорд Лиги убийц",
	found = "Внутри Поместья Черного Ворона",
	hint = [=[Найдите хозяина тайного поместья в восточных холмах, если его слуги вас впустят.]=],
	allegiance = "Лига убийц · Черный Ворон",
	aliases = { "Джорах Черный Ворон", "мастер Черный Ворон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лорд Джорах Черный Ворон — хозяин Поместья Черного Ворона и глава Лиги убийц. Его разбойники — самые искусные в северных землях, и они не служат ни одному королю. Он любезен с гостями, щедр к тем, кто хорошо ему служит, и очень скрытен в собственных делах. Он не говорит, чего хочет. Он просто просит и ждет, у кого хватит ума это исполнить.]=],
		},
		{
			title = "Значение",
			text = [=[Сообщество, которым правит Джорах, — старейший враг {link:syndicate}Синдиката{/link} в {link:alterac-mountains}Альтерак{/link}е. Его агенты не пытаются перебить Синдикат поодиночке, ибо врагов слишком много. Они крадут эмблемы его членов, а с опозоренными затем расправляются свои же. Это более тихая война, чем та, что ведет {link:southshore}Южнобережье{/link}, и, возможно, более действенная.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он правит Поместьем Черного Ворона и разбойниками, которые там обучаются.
• Он ведет против {link:syndicate}Синдикат{/link}а долгую войну воровства и страха.
• Он призывает проверенных разбойников, чтобы вернуть то, что ему дорого, и щедро их награждает.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Мало что написано о жизни лорда до сообщества и о том, как его дом получил эти холмы. Эта запись хранит лишь то, что открывают его деяния.]=],
		},
	},
	chapters = {
		{
			title = "Простая просьба",
			hint = "Откликнитесь на зов лорда Черного Ворона.",
			text = [=[Зов пришел тайно, и Джорах встретил гостя радушно. Он лишился одной мелочи: синей сумки. Воры, которые ее взяли, были уже мертвы. Они не сумели ее открыть и продали Древобрюхам Азшары, а те приняли ее за священную реликвию. Джорах хотел получить ее обратно, по возможности без шума.]=],
		},
		{
			title = "Лазурный ключ",
			hint = "Принесите ключ от пропавшей сумки.",
			text = [=[Сумка была запечатана чарами, а ключ от нее был у зеленого дракона в затонувшем храме Болота Печали. Когда ключ вернули, Джорах открыл сумку. Золотой свет хлынул на него, и глаза его широко раскрылись. Что он увидел внутри, он не сказал.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:ravenholdt-manor}Поместье Черного Ворона{/link}, приглашение, посланное от его имени]=],
		},
		{ text = "Эмблемы {link:syndicate}Синдикат{/link}а" },
		{ text = "Простая просьба" },
		{ text = "Запечатанная лазурная сумка" },
		{ text = "Лазурный ключ" },
	},
	bonds = {
		{ id = "fahrad", name = "Фарад", note = "его великий мастер разбойников" },
		{ id = "lord-aliden-perenolde", name = "Лорд Алиден Перенольд", note = "лорд его врагов" },
	},
})

