Translate("ruRU", "aiden-perenolde", {
	title = "Айден Перенольд",
	subtitle = "Король-предатель Альтерака",
	hint = "Узнайте историю короля, который продал свои горы Орде.",
	allegiance = "Королевство Альтерак",
	aliases = { "король Перенольд", "лорд Айден Перенольд" },
	sections = {
		{
			title = "Обзор",
			text = [=[Айден Перенольд был последним королем {link:alterac-mountains}Альтерак{/link}а. Это был человек с тихим голосом и тонким воспитанием, владевший прекрасным мечом и ни разу не пустивший его в ход. Соперники в {link:alliance}Альянс{/link}е считали его трусом. Сам он считал себя единственным королем, достаточно мудрым, чтобы видеть: Орду победить нельзя. Во {link:second-war}Вторую войну{/link} он предал Альянс, чтобы спасти собственное королевство, и тем самым его потерял.]=],
		},
		{
			title = "Значение",
			text = [=[Его измена — причина, по которой {link:alterac-mountains}Альтерак{/link} лежит в руинах. Его наследники все еще грезят о короне, которой он лишился, а {link:syndicate}Синдикат{/link}, что они возглавляют, — его горькое наследие.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он вступил в {link:alliance}Альянс Лордерона{/link} лишь неохотно и сомневался в нем с самого начала.
• Он перегородил перевалы своих гор, а затем заключил тайный договор с вождем {link:orgrim-doomhammer}Оргримом Молотом Рока{/link} и открыл их.
• Он убил гонца, принесшего призыв о войсках от полководца {link:anduin-lothar}Лотар{/link}а, и спрятал тело в своем замке.
• Король {link:terenas-menethil}Теренас{/link} низложил его и заточил в его дворце в разрушенной столице.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не сообщает, когда и как умер Айден Перенольд. Говорят, что в заточении рассудок ему изменил. Его семью держали под надзором, а его старший сын, {link:lord-aliden-perenolde}Алиден{/link}, тщетно пытался очистить имя рода.]=],
		},
	},
	chapters = {
		{
			title = "Открытые перевалы",
			hint = "Узнайте, почему Орда так быстро перешла Альтерак.",
			text = [=[Когда {link:horde}Орда{/link} подошла к горам, Перенольд послал птицу к ее вождю и встретился с ним ночью. Он нашел {link:orcs}орк{/link}а воспитанным и честным. Они заключили договор: Орда пройдет беспрепятственно, а {link:alterac-mountains}Альтерак{/link} пощадят. Перенольд отвел своих солдат на север и оставил южные перевалы пустыми. Переход, который должен был занять месяцы, занял два дня. Перевалы закрылись снова, лишь когда {link:thoras-trollbane}Торас Троллебой{/link} из {link:stromgarde-keep}Стромгард{/link}а вошел в Альтерак и обратил против короля его же генерала.]=],
		},
		{
			title = "Утраченное наследие",
			hint = "Верните тиару королевского дома Альтерака.",
			text = [=[Когда пал {link:alterac-mountains}Альтерак{/link}, тиара Перенольдов пропала. Ее сделали ювелиры-{link:dwarves}дворф{/link}ы, и изумруды в ней были лучшими, какие у них имелись. Собиратели в {link:stormwind-city}Штормград{/link}е до сих пор хотят ее заполучить. {link:nak}Нак{/link}онец она объявилась в руках {link:ogres}огр{/link}а-мага, который ищет сокровища в руинах того самого города, где король когда-то ее носил.]=],
		},
	},
	mentions = {
		{ text = "Тиара Перенольдов" },
		{ text = "Смерть дворянам, против дворян его павшего двора" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Лорд Алиден Перенольд", note = "его старший сын" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "его тайный союзник" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "король, который его низложил" },
		{ id = "grel-borg-the-miser", name = "Грел'борг Скряга", note = "владеет тиарой его семьи" },
	},
})

Translate("ruRU", "lord-aliden-perenolde", {
	title = "Лорд Алиден Перенольд",
	subtitle = "Лорд Синдиката",
	found = "Овчарня Дандреда, на берегу Озера Лордамер",
	hint = "Ищите лорда Синдиката в его поместье на берегу озера.",
	allegiance = "Синдикат · Дом Перенольдов",
	aliases = { "Алиден Перенольд", "Алиден" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лорд Алиден Перенольд — старший сын короля-предателя {link:alterac-mountains}Альтерак{/link}а и глава {link:syndicate}Синдиката{/link}. Он величает себя владыкой гор, которые потерял его отец. Из своего поместья в Овчарне Дандреда он направляет воров, убийц и падших дворян по всему Альтераку и {link:hillsbrad-foothills}Хилсбрад{/link}у. Своих замыслов он не скрывает. Он намерен вернуть эту землю и обратить в рабов {link:orcs}орк{/link}ов, которые ему противостоят.]=],
		},
		{
			title = "Значение",
			text = [=[Алиден — наследник позора {link:alterac-mountains}Альтерак{/link}а. Когда-то он пытался восстановить доброе имя своего дома. Теперь он стал тем, кем его всегда называли враги.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он руководит {link:syndicate}Синдикат{/link}ом из Овчарни Дандреда, и рядом с ним стоит {link:argus-wake}орден Пробуждения Аргуса{/link}.
• Он держит пленников из Орды рабами в лагерях {link:alterac-mountains}Альтерак{/link}а.
• Он держит при себе любовницей молодую женщину по имени {link:elysa}Элиза{/link} и подарил ей подвеску, взятую в {link:durnholde-keep}Дарнхольд{/link}е.]=],
		},
	},
	chapters = {
		{
			title = "Наследие лорда Блэкмура",
			hint = [=[Освободите орка, которого Синдикат держит в плену, и выслушайте, что он узнал.]=],
			text = [=[Алиден лично пришел посмотреть на своего пленника {link:gol-dir}Гол'дир{/link}а. Он хвалился перед {link:orcs}орк{/link}ом своими замыслами: орки, которые ему не покорятся, станут рабами, как некогда и намеревались его отец и его старый наставник, {link:aedelas-blackmoore}Эделас Блэкмур{/link}. Рядом с ним стояла {link:elysa}Элиза{/link}. На ее шее висела подвеска, которую Гол'дир узнал сразу, ибо именно ее послал его искать вождь.]=],
		},
		{
			title = "Дар Тареты",
			hint = "Отнесите ответ орков в поместье на берегу озера.",
			text = [=[{link:orcs}Орки{/link} Мельницы Таррен ответили на его похвальбу сталью. Они пришли в Овчарню Дандреда и убили лорда {link:syndicate}Синдикат{/link}а в его собственном доме. {link:elysa}Элиза{/link} молила о пощаде и сразу отдала подвеску. Она сказала, что не хочет никакой памяти о нем.]=],
		},
	},
	mentions = {
		{ text = "Наследие лорда {link:aedelas-blackmoore}Блэкмур{/link}а" },
		{ text = "Лорд Алиден Перенольд" },
		{ text = "{link:dar}Дар{/link} Тареты" },
	},
	bonds = {
		{ id = "aiden-perenolde", name = "Айден Перенольд", note = "его отец" },
		{ id = "elysa", name = "Элиза", note = "его любовница" },
		{ id = "nagaz", name = "Нагаз", note = "посланник, что стоит рядом с ним" },
		{ id = "aedelas-blackmoore", name = "Эделас Блэкмур", note = "его наставник" },
		{ id = "gol-dir", name = "Гол'дир", note = "его пленник" },
		{ id = "lord-jorach-ravenholdt", name = "Лорд Джорах Черный Ворон", note = "его враг" },
	},
})

Translate("ruRU", "elysa", {
