Translate("ruRU", "gol-dir", {
	title = "Гол'дир",
	subtitle = "Глава экспедиции вождя",
	found = "В плену в лагере Синдиката в Странбраде",
	hint = [=[Освободите орка, которого Синдикат держит в цепях в своем лагере.]=],
	allegiance = "Орда",
	sections = {
