	hint = [=[Ищите старого шамана, который правит из Крепости Северного Волка на южном краю Альтеракской долины.]=],
	allegiance = "Клан Северного Волка · Орда",
	aliases = { "Дрек'Тар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дрек'Тар — старший шаман {link:frostwolf-clan}клана Северного Волка{/link} и генерал его воинов в {link:alterac-mountains}Альтерак{/link}ской долине. Он слеп, и он стар. Он был шаманом клана еще на Дреноре и последовал за своим народом в изгнание в эти горы. Давным-давно он взял под опеку молодого {link:orcs}орк{/link}а {link:thrall}Тралла{/link} и научил его говорить с духами. Теперь он ведет клан Северного Волка из его крепости на юге долины.]=],
		},
		{
			title = "Значение",
			text = [=[Дрек'Тар — учитель вождя. Через него древние пути шаманов вернулись к {link:orcs}орк{/link}ам, а через его ученика они вернулись ко всей {link:horde}Орде{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он сберег {link:frostwolf-clan}клан Северного Волка{/link} в изгнании в {link:alterac-mountains}Альтерак{/link}е.
• Он научил будущего вождя пути шамана и открыл ему, кем были его родители.
• Он руководит обороной Альтеракской долины от Стражи Грозовой Вершины.]=],
		},
	},
	chapters = {
		{
			title = "Сын Дуротана",
			hint = "Узнайте, как вождь пришел к клану Северного Волка.",
			text = [=[Когда молодой {link:orcs}орк{/link}, воспитанный людьми, пришел в лагерь клана Северного Волка, при нем было рваное одеяльце его младенчества. Дрек'Тар узнал знаки на нем. Чужак был сыном вождя Дуротана, который увел клан в изгнание и был убит вместе со своей подругой. Старый шаман испытал гордость и смирение молодого орка, а затем научил его путям духов.]=],
		},
		{
			title = "На защиту клана Северного Волка",
			hint = "Встаньте рядом с кланом Северного Волка в его долине.",
			text = [=[Теперь {link:dwarves}дворф{/link}ы пришли в долину, что укрывала {link:frostwolf-clan}клан Северного Волка{/link} в самые темные его годы. Клан, который дорог вождю, под ударом, и призыв разнесся по всей Орде. Воинов посылают к северу от Мельницы Таррен, к воеводе Лаггронду, который испытывает их у входа в долину, прежде чем они пойдут в бой.]=],
		},
	},
	mentions = {
		{ text = "На защиту клана Северного Волка" },
		{ text = "Битва за {link:alterac-mountains}Альтерак{/link}" },
		{ text = "Испытательный полигон" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его ученик и вождь" },
		{ id = "vanndar-stormpike", name = "Вандар Штормпайк", note = "его враг" },
		{ id = "voggah-deathgrip", name = "Воггах Хватка Смерти", note = "посылает воинов ему на помощь" },
	},
})

Translate("ruRU", "crushridge-ogres", {
	title = "Огры Раздробленного Хребта",
	aliases = { "Раздробленный Хребет", "огр Раздробленного Хребта", "клан Раздробленного Хребта" },
	sections = {
		{
			title = "Обзор",
			text = [=[Огры Раздробленного Хребта — отряд {link:ogres}огров{/link}, захвативший руины старой столицы {link:alterac-mountains}Альтерак{/link}а. Громилы, молотобойцы, поджигатели войны, каратели и маги заполняют улицы, по которым когда-то ездили короли Альтерака. Они вырыли большое логово в холмах неподалеку и второе — глубже в горах, а их дозоры стерегут перекресток на пути к Мельнице Таррен.]=],
		},
		{
			title = "Корона Воли",
			text = [=[Огры Раздробленного Хребта пришли в {link:alterac-mountains}Альтерак{/link} не по своей воле. Их полководец {link:mug-thol}Маг'тол{/link} был подчинен {link:sylvanas-windrunner}Сильваной Ветрокрылой{/link}, и она послала его отряд в горы вернуть реликвию, что зовется Короной Воли. Маг'тол нашел корону и надел ее. Она освободила его от власти Темной Госпожи, и его {link:ogres}огр{/link}ы вошли за ним в руины уже сами себе хозяевами. Рядом с ним стоят трое помощников — {link:tharg}Тарг{/link}, Грязекоп и Гломмус, а огр-маг {link:grel-borg-the-miser}Грел'борг{/link} рыщет по городу в поисках сокровищ.]=],
		},
		{
			title = "Враги со всех сторон",
			text = [=[{link:forsaken}Отрекшиеся{/link} из Мельницы Таррен хотят получить корону, а с нею головы полководца и его помощников. Солдаты Южнобережья боятся, что {link:ogres}огр{/link}ы спустятся в предгорья, и их маршал платит награду за каждого убитого огра. Огры также воевали с {link:syndicate}Синдикатом{/link} за руины королевства, на которое притязают и те, и другие.]=],
		},
	},
})

Translate("ruRU", "argus-wake", {
	title = "Пробуждение Аргуса",
	aliases = { "орден Пробуждения Аргуса" },
	sections = {
		{
			title = "Обзор",
			text = [=[Пробуждение Аргуса — тайный орден, который сделался союзником {link:syndicate}Синдиката{/link} в {link:alterac-mountains}Альтерак{/link}е. Его маги теней ждут в {link:the-uplands}Высокогорье{/link}, а его иерофант, {link:orcs}орк{/link} {link:nagaz}Нагаз{/link}, стоит рядом с лордом {link:lord-aliden-perenolde}Алиден{/link}ом Перенольдом. Дворяне Альтерака верят, что нашли могущественных друзей. Они ошибаются.]=],
		},
		{
			title = "Письмо",
			text = [=[Правда вышла на свет в письме, найденном в лагере {link:syndicate}Синдикат{/link}а. Оно было написано шифром столь редким, что его не смог прочесть даже хранитель знаний Южнобережья, и письмо пришлось везти к геологу в {link:ironforge}Стальгорн{/link}. {link:nagaz}Нагаз{/link} написал его главе ордена, к которому обращался как к своему господину, назначенному неким советом. Синдикат, писал он, под руководством ордена отвоюет {link:alterac-mountains}Альтерак{/link}, а затем возьмет {link:stromgarde-keep}Стромгард{/link}. Имея собственную страну и собственную опору власти, орден подготовит путь тому, что он назвал Третьим Воинством. Подписал он письмо именем владыки {link:sargeras}Саргерас{/link}а.]=],
		},
		{
			title = "Что остается неизвестным",
			text = [=[Мировой судья Южнобережья {link:magistrate-henry-maleb}Малеб{/link} послал охотников за иерофантом и его магами. И все же судья знает, что {link:nagaz}Нагаз{/link} был лишь слугой. Кто возглавляет орден Пробуждения Аргуса и как глубоко уходят его корни, в {link:southshore}Южнобережье{/link} не может сказать никто.]=],
		},
	},
})

Translate("ruRU", "stormpike-guard", {
	title = "Стража Грозовой Вершины",
	aliases = { "экспедиция Грозовой Вершины", "дворфы Грозовой Вершины" },
	sections = {
		{
			title = "Обзор",
			text = [=[Стража Грозовой Вершины — экспедиция {link:dwarves}дворфов{/link} клана Грозовой Вершины в {link:alterac-mountains}Альтерак{/link}ской долине под началом генерала {link:vanndar-stormpike}Вандар{/link}а Штормпайка. Из своей крепости Дун Болдар на севере долины они обыскивают землю в поисках руды и реликвий своего прошлого. В их рядах сражаются люди, {link:gnomes}гном{/link}ы и ночные эльфы {link:alliance}Альянса{/link}.]=],
		},
		{
			title = "Долг",
			text = [=[Экспедиция обернулась войной. Король {link:magni-bronzebeard}Магни Бронзобород{/link} объявил взятие долин {link:alterac-mountains}Альтерак{/link}а долгом {link:kingdom-of-ironforge}королевства Стальгорн{/link}, и дворфы Грозовой Вершины сражаются за них с троллями Ледяной Секиры и {link:orcs}орк{/link}ами {link:frostwolf-clan}клана Северного Волка{/link}. С ними идут ученые {link:explorers-league}Лиги исследователей{/link}, уверенные, что долина хранит артефакты, которые стоят этой борьбы. Орки называют их захватчиками. {link:dwarves}Дворфы{/link} называют долину своей по праву.]=],
		},
		{
			title = "В наши дни",
			text = [=[У входа в туннель, ведущий в долину, офицеры Грозовой Вершины принимают солдат {link:alliance}Альянс{/link}а, испытывают их в пещерах долины и вручают им знаки отличия Стражи. Бараны {link:dwarves}дворф{/link}ов, выращенные на ранчо Янтарлен в {link:dun-morogh}Дун Мороге{/link}, идут на север, чтобы усилить экспедицию.]=],
		},
	},
})

Translate("ruRU", "frostwolf-clan", {
	title = "Клан Северного Волка",
	aliases = { "Северные Волки", "клан Северного Волка", "орки Северного Волка" },
	sections = {
		{
			title = "Обзор",
			text = [=[Клан Северного Волка — клан {link:orcs}орк{/link}ов, который живет в {link:alterac-mountains}Альтерак{/link}ской долине. Это клан отца вождя {link:thrall}Тралла{/link}, и вождь им дорожит. Его воины ездят на {link:ogres}огр{/link}омных белых волках гор, а его старший шаман, {link:drek-thar}Дрек'Тар{/link}, ведет клан из Крепости Северного Волка на юге долины.]=],
		},
		{
			title = "Изгнание",
			text = [=[На Дреноре клан Северного Волка был гордым кланом под началом своего вождя Дуротана. Когда {link:orcs}орк{/link}и пришли на {link:azeroth}Азерот{/link}, Дуротан выступил против чернокнижника {link:gul-dan}Гул'дана{/link} и темного пути, на который встала {link:horde}Орда{/link}. За это его клан был изгнан в {link:alterac-mountains}Альтеракские горы{/link}. Позднее Дуротан и его подруга покинули долину, и обоих убили слуги того же чернокнижника. Их младенца-сына нашел человеческий офицер и вырастил рабом в {link:durnholde-keep}Дарнхольд{/link}е. Клан Северного Волка сносил холод и долгие годы в одиночестве, и вдали от магии Скверны, которой жила Орда, его шаманы заново познали пути духов.]=],
		},
		{
			title = "Возвращение сына",
			text = [=[Годы спустя в их лагерь пришел молодой {link:orcs}орк{/link}, беглец из {link:durnholde-keep}Дарнхольд{/link}а. Это был сын их вождя. {link:drek-thar}Дрек'Тар{/link} научил его путям шамана, и из долины {link:thrall}Тралл{/link} отправился освобождать орков из лагерей и строить новую Орду.]=],
		},
		{
			title = "В наши дни",
			text = [=[Теперь в долину пришли {link:dwarves}дворф{/link}ы {link:stormpike-guard}Стражи Грозовой Вершины{/link}. Клан Северного Волка не отдаст свой дом, и {link:horde}Орда{/link} откликнулась на его зов.]=],
		},
	},
})
